/** تمام ترکیب‌های شهر+صنعت+بانک برای generateStaticParams */
export function getCityIndustryBankCombos(): { city: string; industry: string; bank: string }[] {
 const combos: { city: string; industry: string; bank: string }[] = [];
 for (const city of cities) {
 for (const industry of industryInfos) {
 for (const bank of bankNames) {
 combos.push({ city: city.slug, industry: industry.slug, bank: bank.slug });
 }
 }
 }
 return combos;
}

/** یافتن شهر بر اساس slug */
export function getCityBySlug(slug: string): CityData | undefined {
 return cities.find((c) => c.slug === slug);
}

/** یافتن صنعت بر اساس slug */
export function getIndustryInfoBySlug(slug: string): IndustryInfo | undefined {
 return industryInfos.find((i) => i.slug === slug);
}

/** یافتن بانک بر اساس slug */
export function getBankBySlug(slug: string): BankData | undefined {
 return bankNames.find((b) => b.slug === slug);
}
